void context_store_protected_registry_successor_result::set_authenticated(const context_store_protected_registry_successor_body&b,const context_store_protected_registry_key_record&k,const context_store_format_digest&d,const context_store_format_digest&a,const context_store_format_digest&c,const uint8_t*p,size_t n)noexcept{carrier_.body_=b;carrier_.key_id_=k.key_id;carrier_.key_generation_=k.generation;carrier_.envelope_digest_=d;carrier_.authority_binding_=a;carrier_.key_continuity_commitment_=c;carrier_.envelope_size_=n;std::copy_n(p,n,carrier_.envelope_.begin());carrier_.valid_=true;status=context_store_protected_registry_successor_status::authenticated_unadmitted;}
context_store_protected_registry_successor_result context_store_encode_protected_registry_successor_v1(const context_store_protected_registry_successor_body&b,const context_store_protected_registry_key_record&k,uint8_t*out,size_t cap)noexcept{context_store_protected_registry_successor_result r;if(!bodyok(b)||!keyok(k)||k.disposition!=context_store_key_disposition::active||!out){r.status=context_store_protected_registry_successor_status::invalid_policy;return r;}std::array<uint8_t,768>body{},ai{};writer bw{body.data(),body.size()};context_store_format_digest t{},d{},a{},c{};bool ok=body_enc(b,bw);writer aw{ai.data(),ai.size()};ok=ok&&aw.head(5,4)&&aw.u(0)&&aw.raw(body.data(),bw.n)&&aw.u(1)&&aw.ts(k.key_id.bytes.data(),k.key_id.size)&&aw.u(2)&&aw.u(1)&&aw.u(3)&&aw.u(k.generation)&&tag(k,ai.data(),aw.n,t);writer ew{out,std::min(cap,context_store_protected_registry_successor_max_bytes)};bool encoded=ok&&ew.head(5,2)&&ew.u(0)&&ew.raw(ai.data(),aw.n)&&ew.u(1)&&ew.bs(t.data(),32);ok=encoded&&digest(out,ew.n,d)&&binding(k,d,a)&&continuity(k,c);wipe(body.data(),body.size());wipe(ai.data(),ai.size());wipe(t.data(),32);if(!ok){r.status=encoded?context_store_protected_registry_successor_status::invalid_policy:context_store_protected_registry_successor_status::output_too_small;wipe(d.data(),32);wipe(a.data(),32);wipe(c.data(),32);return r;}r.encoded_size=ew.n;r.set_authenticated(b,k,d,a,c,out,ew.n);wipe(d.data(),32);wipe(a.data(),32);wipe(c.data(),32);return r;}
context_store_protected_registry_successor_result context_store_verify_protected_registry_successor_v1(const uint8_t*p,size_t n,const context_store_protected_registry_key_record&k)noexcept{context_store_protected_registry_successor_result out;if(!p||!n||n>1024)return out;if(!keyok(k)){out.status=context_store_protected_registry_successor_status::invalid_policy;return out;}reader r{p,n};uint64_t z,alg,gen;const uint8_t*ip,*tp;size_t in,tn;if(!r.head(5,z)||z!=2||!r.ex(0))return out;size_t ao=r.o;if(!r.head(5,z)||z!=4||!r.ex(0))return out;context_store_protected_registry_successor_body b;if(!body_parse(r,b)||!r.ex(1)||!r.bytes(3,ip,in)||!r.ex(2)||!r.u(alg)||!r.ex(3)||!r.u(gen)||alg!=1)return out;size_t an=r.o-ao;if(!r.ex(1)||!r.bytes(2,tp,tn)||tn!=32||r.o!=n)return out;context_store_registered_id id;if(!in||in>128)return out;id.size=(uint8_t)in;std::copy_n(ip,in,id.bytes.begin());if(!idok(id))return out;if(!eqid(id,k.key_id)){out.status=context_store_protected_registry_successor_status::unknown_key;return out;}if(k.disposition==context_store_key_disposition::revoked){out.status=context_store_protected_registry_successor_status::revoked_key;return out;}if(k.disposition==context_store_key_disposition::read_disabled){out.status=context_store_protected_registry_successor_status::read_disabled_key;return out;}if(k.disposition!=context_store_key_disposition::active){out.status=context_store_protected_registry_successor_status::invalid_policy;return out;}if(gen!=k.generation){out.status=context_store_protected_registry_successor_status::key_generation_mismatch;return out;}context_store_format_digest e{},got{},d{},a{},c{};std::copy_n(tp,32,got.begin());if(!tag(k,p+ao,an,e)||!eqd(e,got)){out.status=context_store_protected_registry_successor_status::authentication_failed;wipe(e.data(),32);wipe(got.data(),32);return out;}if(!digest(p,n,d)||!binding(k,d,a)||!continuity(k,c)){out.status=context_store_protected_registry_successor_status::invalid_policy;wipe(e.data(),32);wipe(got.data(),32);wipe(d.data(),32);wipe(a.data(),32);wipe(c.data(),32);return out;}out.encoded_size=n;out.set_authenticated(b,k,d,a,c,p,n);wipe(e.data(),32);wipe(got.data(),32);wipe(d.data(),32);wipe(a.data(),32);wipe(c.data(),32);return out;}
const char*context_store_protected_registry_successor_status_name(context_store_protected_registry_successor_status s)noexcept{switch(s){case context_store_protected_registry_successor_status::authenticated_unadmitted:return "authenticated-unadmitted";case context_store_protected_registry_successor_status::structural_rejection:return "structural-rejection";case context_store_protected_registry_successor_status::output_too_small:return "output-too-small";case context_store_protected_registry_successor_status::invalid_policy:return "invalid-policy";case context_store_protected_registry_successor_status::unknown_key:return "unknown-key";case context_store_protected_registry_successor_status::revoked_key:return "revoked-key";case context_store_protected_registry_successor_status::read_disabled_key:return "read-disabled-key";case context_store_protected_registry_successor_status::key_generation_mismatch:return "key-generation-mismatch";case context_store_protected_registry_successor_status::authentication_failed:return "authentication-failed";}return "unknown";}
